export function getYesterdayWindow(dateStr: string) {
  // dateStr like '2026-04-24'
  const d = new Date(dateStr + 'T00:00:00');
  const start = new Date(d);
  start.setDate(start.getDate() - 1);
  const end = new Date(d);
